632→
633→export type FramePredicate =
634→  | { kind: 'slowFrames'; thresholdMs?: number }
635→  | { kind: 'markerSpike'; markerName: string; thread?: string; minSelfMs: number }
636→  | { kind: 'frameList'; frames: number[] };
637→
638→export interface CorrelateFrameSetsArgs {
639→  runId: string;
640→  setA: FramePredicate;
641→  setB: FramePredicate;
642→}
643→
644→export interface CorrelateFrameSetsResult {
645→  data: {
646→    sizeA: number;
647→    sizeB: number;
648→    intersection: number;
649→    union: number;
650→    jaccard: number;
651→    pctAinB: number;
652→    pctBinA: number;
653→    sampleOverlapFrames: number[];
654→  };
655→  provenance: Provenance;
656→}
657→
658→function resolvePredicate(
659→  db: Database.Database,
660→  runId: string,
661→  pred: FramePredicate
662→): Set<number> {
663→  if (pred.kind === 'frameList') {
664→    return new Set(pred.frames);
665→  }
666→
667→  if (pred.kind === 'slowFrames') {
668→    // Compute threshold = p95 of ms_frame if not provided
669→    const metas = db
670→      .prepare(
671→        'SELECT ms_frame FROM prism_frame_meta WHERE run_id = ? ORDER BY ms_frame'
672→      )
673→      .all(runId) as Array<{ ms_frame: number }>;
674→
675→    const threshold =
676→      pred.thresholdMs ??
677→      metas[Math.floor(metas.length * 0.95)]?.ms_frame ??
678→      0;
