282→
283→export interface ScanMetricOverFramesArgs {
284→  runId: string;
285→  markerName: string;
286→  thread?: string;
287→  metric?: 'selfMs' | 'totalMs';
288→}
289→
290→export interface ScanMetricOverFramesResult {
291→  data: StatsPack;
292→  provenance: Provenance;
293→}
294→
295→export function scanMetricOverFrames(
296→  db: Database.Database,
297→  args: ScanMetricOverFramesArgs
298→): ScanMetricOverFramesResult {
299→  const { runId, markerName, thread, metric = 'selfMs' } = args;
300→  const col = metric === 'totalMs' ? 'total_ms' : 'self_ms';
301→
302→  // Get all frame indices for this run (the full time axis)
303→  const allFrames = db
304→    .prepare(
305→      'SELECT frame_index FROM prism_frame_meta WHERE run_id = ? ORDER BY frame_index'
306→    )
307→    .all(runId) as Array<{ frame_index: number }>;
308→
309→  // Get per-frame sums where the marker is present
310→  let markerSql = `
311→    SELECT frame_index, SUM(${col}) AS v
312→    FROM prism_frame_marker_samples
313→    WHERE run_id = ? AND marker_name = ?
314→  `;
315→  const params: unknown[] = [runId, markerName];
316→  if (thread) {
317→    markerSql += ' AND thread = ?';
318→    params.push(thread);
319→  }
320→  markerSql += ' GROUP BY frame_index';
321→
322→  const markerRows = db.prepare(markerSql).all(...params) as Array<{
323→    frame_index: number;
324→    v: number;
325→  }>;
326→
327→  // Build dense series aligned to allFrames (zero for absent frames)
328→  const markerMap = new Map<number, number>();
329→  for (const r of markerRows) markerMap.set(r.frame_index, r.v);
330→
331→  const values: number[] = [];
332→  const frameIndices: number[] = [];
333→  for (const { frame_index } of allFrames) {
334→    values.push(markerMap.get(frame_index) ?? 0);
335→    frameIndices.push(frame_index);
336→  }
337→
338→  const stats = computeStatsPack(values, frameIndices);
339→
340→  return {
341→    data: stats,
342→    provenance: {
343→      runId,
344→      tool: 'scanMetricOverFrames',
345→      args: args as Record<string, unknown>,
346→    },
347→  };
348→}
