 1→/**
 2→ * Prism 阶段一核心类型：Finding / DataRequest / ToolCall。
 3→ *
 4→ * 设计锚点（见 docs/PRISM-CHARTER.md）：
 5→ * - F1 分析师非作文机：每个 Finding 的每条断言都回溯到一次可复现、带 provenance 的查询。
 6→ *   evidence 不是自由文本，而是挂着真实 ToolCall（tool + args + 归约结果）。
 7→ * - F4 能力回路：DataRequest 是"LLM 想查却查不到"的一等产物，喂给 provider 自举。
 8→ * - 复用 web/shared/perf-model.ts 的 Insight 语义（severity/confidence/conclusion/recommendation），
 9→ *   但 evidence 升级为可回溯的 ToolCall 引用，而非 {source, detail:string}。
10→ *
11→ * 通用性（架构第一原则·Finding 开放可扩展）：evidence 里不写任何单源硬编码字段，
12→ * 只有通用的 { tool, args, resultDigest }。加新源/新工具无需改本类型。
13→ */
14→
15→export type PrismSeverity = 'critical' | 'high' | 'medium' | 'low' | 'info';
16→export type PrismConfidence = 'high' | 'medium' | 'low';
17→
18→/** 一次查询工具调用的可回溯记录。evidence 的原子单位。 */
19→export interface ToolCall {
20→  /** 工具名，如 'scanMetricOverFrames'。 */
21→  tool: string;
22→  /** 调用入参（原样，可复现）。 */
23→  args: Record<string, unknown>;
24→  /**
25→   * 该次调用返回的**归约结果摘要**（小对象，非原始逐帧数组，见 token 红线 DR-12）。
26→   * 直接内嵌，使 Finding 自包含、可离线审计——读 Finding 即见支撑数字，无需重跑。
27→   */
28→  resultDigest: unknown;
29→  /** 可选：产生该调用的 run。 */
30→  runId?: string;
31→}
32→
33→/**
34→ * 一条 Prism 发现。由 Phase A 探索内核在自由探索中产出。
35→ * 铁律（F1）：没有 evidence（至少一条 ToolCall）就不允许存在——无证据不下结论。
36→ */
37→export interface Finding {
38→  /** 稳定 id，便于跨阶段引用/去重（如 'wait.main.semaphore'）。 */
39→  id: string;
40→  /** 普通话结论先行（F6 TL;DR 的原料）。 */
41→  conclusion: string;
42→  severity: PrismSeverity;
43→  confidence: PrismConfidence;
44→  /**
45→   * 可回溯证据链：支撑本结论的真实工具调用。至少一条。
46→   * 这是 F1 的落地——"点开看支撑它的查询和数字"。
47→   */
48→  evidence: ToolCall[];
49→  /**
50→   * 可选：AI 的推理链（为什么这些证据支撑这个结论）。
51→   * 与 evidence 分离：evidence 是事实，reasoning 是解释。
52→   */
53→  reasoning?: string;
54→  /** 自我批判回合（DR-24）对本 finding 的审查/补查/修改记录。 */
55→  selfCritique?: string;
56→  /** 可选：优化建议（阶段三源码锚定后才带 confidence 的代码建议；阶段一仅数据侧建议）。 */
57→  recommendation?: string;
58→  /**
59→   * 可选：本 finding 触及的符号/marker 名，供阶段三源码锚定（F5）预留挂点。
60→   * 阶段一可填 marker 名，不做源码检索。
61→   */
62→  symbols?: string[];
63→  /** 可选：AI 给的标签，便于 Phase B 分组（如 'thread-wait' / 'periodicity' / 'tail-latency'）。 */
64→  tags?: string[];
65→}
66→
67→/**
68→ * 数据缺口请求（F4 能力回路的一等产物）。
69→ * 当 Phase A 里 LLM 想查某维度、现有工具给不出时产出。
70→ * 短期：人/通用执行器满足；长期：高频复现的固化成新工具/新 provider 字段。
71→ */
72→export interface DataRequest {
73→  /** 稳定 id，便于跨版本统计高频复现。 */
74→  id: string;
75→  /** 一句话：想要什么数据/什么查询能力。 */
76→  want: string;
77→  /** 为什么要——支撑哪个假设 H / 想验证什么。 */
78→  rationale: string;
79→  /** 可选：AI 猜测这属于哪个数据轴（marker/frame/thread/depth/set/新轴如 memory）。 */
80→  suspectedAxis?: string;
81→  /** 可选：现有哪个工具最接近但差在哪。 */
82→  closestExistingTool?: string;
83→}
84→
85→/** Phase A 探索的完整产出。 */
86→export interface ExploreResult {
87→  runId: string;
88→  /** 结构化发现图（Phase B 的唯一输入）。 */
89→  findings: Finding[];
90→  /** 本轮探索撞到的数据缺口（喂 F4）。 */
91→  dataRequests: DataRequest[];
92→  /** 可选：探索过程的工具调用总数/轮次等元信息，便于成本审计。 */
93→  meta?: {
94→    toolCallCount?: number;
95→    rounds?: number;
96→    notes?: string[];
97→  };
98→}
